auto Component_empty_283::create (class ContextMenu_root_173 const * parent) -> slint::ComponentHandle<Component_empty_283>{
    auto self_rc = vtable::VRc<slint::private_api::ItemTreeVTable, Component_empty_283>::make();
    auto self = const_cast<Component_empty_283 *>(&*self_rc);
    self->self_weak = vtable::VWeak(self_rc).into_dyn();
    slint::private_api::register_item_tree(&self_rc.into_dyn(), parent->globals->m_window);
    self->init(parent->globals, self->self_weak, 0, 1 , parent);
    return slint::ComponentHandle<Component_empty_283>{ self_rc };
}

Component_empty_283::~Component_empty_283 (){
    if (auto &window = globals->m_window) window->window_handle().unregister_item_tree(this, item_array());
}

